cd /src/libxml2 && python3 - <<'PY'
import re, pathlib
path = pathlib.Path('xinclude.c')
src = path.read_text(encoding='utf-8', errors='replace')

# Replace xmlXIncludeAddTxt function
pattern = re.compile(r"static void\nxmlXIncludeAddTxt\(xmlXIncludeCtxtPtr ctxt, xmlNodePtr txt, const xmlURL url\) \{.*?\n\}\n", re.S)
new_func = r'''static void
xmlXIncludeAddTxt(xmlXIncludeCtxtPtr ctxt, xmlNodePtr txt, const xmlURL url) {
    xmlNodePtr copy;
#ifdef DEBUG_XINCLUDE
    xmlGenericError(xmlGenericErrorContext, "Adding text %s\n", url);
#endif

    if ((ctxt == NULL) || (txt == NULL))
        return;

    /*
     * The XMLReader can free nodes it created while XInclude processing is
     * still caching them. Never cache a node whose lifetime is not clearly
     * owned by the XInclude context. Cache an independent copy instead.
     */
    if (txt->type == XML_TEXT_NODE) {
        copy = xmlNewText(txt->content);
    } else {
        copy = xmlCopyNode(txt, 1);
    }
    if (copy == NULL) {
        xmlXIncludeErrMemory(ctxt, NULL, "processing text");
        return;
    }

    if (ctxt->txtMax == 0) {
        ctxt->txtMax = 4;
        ctxt->txtTab = (xmlNodePtr *) xmlMalloc(ctxt->txtMax *
                                      sizeof(ctxt->txtTab[0]));
        if (ctxt->txtTab == NULL) {
            xmlXIncludeErrMemory(ctxt, NULL, "processing text");
            xmlFreeNode(copy);
            return;
        }
        ctxt->txturlTab = (xmlURL *) xmlMalloc(ctxt->txtMax *
                                      sizeof(ctxt->txturlTab[0]));
        if (ctxt->txturlTab == NULL) {
            xmlXIncludeErrMemory(ctxt, NULL, "processing text");
            xmlFreeNode(copy);
            return;
        }
    }
    if (ctxt->txtNr >= ctxt->txtMax) {
        ctxt->txtMax *= 2;
        ctxt->txtTab = (xmlNodePtr *) xmlRealloc(ctxt->txtTab,
                     ctxt->txtMax * sizeof(ctxt->txtTab[0]));
        if (ctxt->txtTab == NULL) {
            xmlXIncludeErrMemory(ctxt, NULL, "processing text");
            xmlFreeNode(copy);
            return;
        }
        ctxt->txturlTab = (xmlURL *) xmlRealloc(ctxt->txturlTab,
                     ctxt->txtMax * sizeof(ctxt->txturlTab[0]));
        if (ctxt->txturlTab == NULL) {
            xmlXIncludeErrMemory(ctxt, NULL, "processing text");
            xmlFreeNode(copy);
            return;
        }
    }
    ctxt->txtTab[ctxt->txtNr] = copy;
    ctxt->txturlTab[ctxt->txtNr] = xmlStrdup(url);
    ctxt->txtNr++;
}
'''

m = pattern.search(src)
if not m:
    raise SystemExit('Failed to locate xmlXIncludeAddTxt to patch')
src2 = src[:m.start()] + new_func + src[m.end():]

# Patch xmlXIncludeFreeContext to free txtTab node copies.
# Insert loop right before freeing txtTab array.
needle = "    if (ctxt->txtTab != NULL)\n\txmlFree(ctxt->txtTab);\n"
if needle not in src2:
    raise SystemExit('Failed to locate txtTab free in xmlXIncludeFreeContext')
insert = "    if (ctxt->txtTab != NULL) {\n\tfor (i = 0;i < ctxt->txtNr;i++) {\n\t    if (ctxt->txtTab[i] != NULL)\n\t\txmlFreeNode(ctxt->txtTab[i]);\n\t}\n\txmlFree(ctxt->txtTab);\n    }\n"
src2 = src2.replace(needle, insert)

path.write_text(src2, encoding='utf-8')
print('Patched xinclude.c')
PY

